// Cloudflare Worker entry: the OpenNext app, plus cron triggers for the daily reminder emails and the
// hourly IndexNow ping. The schedules are in wrangler.json ("triggers"); the jobs are app/api/cron/*.
// .open-next/worker.js is generated by `opennextjs-cloudflare build`, so this file is left out of tsc/eslint.

import { default as handler } from './.open-next/worker.js';

/** Must match the hourly schedule in wrangler.json */
const HOURLY = '17 * * * *';

interface Env {
  CRON_SECRET?: string;
  [key: string]: unknown;
}
interface Ctx {
  waitUntil(promise: Promise<unknown>): void;
}

export default {
  fetch: handler.fetch,

  async scheduled(event: { cron?: string }, env: Env, ctx: Ctx) {
    // Hourly: tell IndexNow about pages that just changed. Daily (22:00 UTC): reminder emails.
    const job = event.cron === HOURLY ? 'indexnow' : 'reminders';
    const request = new Request(`https://itsfootball.club/api/cron/${job}`, {
      method: 'POST',
      headers: { authorization: `Bearer ${env.CRON_SECRET ?? ''}` },
    });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (res: Response) => {
        console.log(`[cron] ${job} ${res.status}: ${await res.text()}`);
      })
    );
  },
};

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
